# ---- address.R -------------------------------------------------------------
# Location from free-text addresses --------------------------------------------
#
# bd_address() reads each distinct address once, in six steps:
#   1. .find_postcode()    a 4-digit number that is a known post code;
#   2. .find_places()      district, division and thana names among
#                          sequences of 1 to 4 words;
#   3. .find_post_office() a post office named after "P.O." (when there is
#                          no post code);
#   4. .pick_district()    the district, from names, thanas and post code;
#   5. .pick_thana()       the thana inside that district;
#   6. .check_address()    division and post code against the district, and
#                          the status.

# Words that show that a place name is part of a street or institution name
# ("Dhaka Road", "Jessore Road", "Mymensingh Medical College"). The last two
# are Bangla road and sarak.
.street_words <- c("road", "rd", "lane", "ln", "street", "st", "avenue", "ave",
                   "highway", "bypass", "sarak", "sorok", "more", "mor", "medical",
                   "college", "university", "cantonment", "cantt", "bus", "stand",
                   "\u09b0\u09cb\u09a1", "\u09b8\u09dc\u0995")
# Words that mark a division (the last is Bangla bibhag).
.division_words <- c("division", "div", "bibhag", "\u09ac\u09bf\u09ad\u09be\u0997")
# Words before a post office name (the last is Bangla dakghar).
.post_office_words <- c("po", "post", "dakghar", "\u09a1\u09be\u0995\u0998\u09b0")
# Words before a post code.
.postcode_words <- c("code", "postcode", "pc", "zip", "post", "dhaka", "ctg")
# Longest place name looked for, in words ("Cox s Bazar Sadar" has four).
.max_place_words <- 4L

# Scores used to choose between several district names in one address.
# A thana of the district named elsewhere, or a post code in it, is strong
# evidence; being named last is weak evidence (addresses usually end with the
# district); a district name that is also a thana of another district named
# in the address is most likely that thana ("Faridpur, Pabna": Faridpur
# thana in Pabna district).
.score_thana <- 2
.score_postcode <- 2
.score_last <- 0.5
.score_is_thana <- -3

# Words of each address: lower case, English digits, "P.O." as "po" and
# "P.S." as "ps", any punctuation as a space. Bangla letters are kept.
.addr_words <- function(s) {
  s <- tolower(.bn2en(.squish(s)))
  s <- gsub("[\u200c\u200d]", "", s, perl = TRUE)
  s <- gsub("(?<![a-z])p[ ./]*o(?![a-z])", " po ", s, perl = TRUE)
  s <- gsub("(?<![a-z])p[ ./]*s(?![a-z])", " ps ", s, perl = TRUE)
  s <- gsub("['\u2019]", "", s, perl = TRUE)
  s <- gsub("[^a-z0-9\u0980-\u09e5\u09f0-\u09ff]+", " ", s, perl = TRUE)
  lapply(strsplit(trimws(s), " ", fixed = TRUE), function(w) w[w != ""])
}

# All sequences of 1 to 4 words of all addresses, with their keys, built at
# once as plain vectors (one data frame per address would be slow).
# a = address, s and e = first and last word.
.addr_spans <- function(words) {
  n <- lengths(words)
  a <- s <- txt <- vector("list", .max_place_words)
  for (len in seq_len(.max_place_words)) {
    ok <- which(n >= len)
    cnt <- n[ok] - len + 1L
    a[[len]] <- rep(ok, cnt)
    s[[len]] <- sequence(cnt)
    flat <- unlist(words[ok], use.names = FALSE)
    off <- rep(cumsum(c(0L, n[ok]))[seq_along(ok)], cnt)
    parts <- lapply(0:(len - 1L), function(k) flat[off + s[[len]] + k])
    txt[[len]] <- if (length(parts[[1L]])) do.call(paste, parts) else character(0)
  }
  len <- rep(seq_len(.max_place_words), lengths(a))
  sp <- data.frame(a = unlist(a), s = unlist(s), txt = unlist(txt), stringsAsFactors = FALSE)
  sp$e <- sp$s + len - 1L
  sp <- sp[order(sp$a, -(sp$e - sp$s), sp$s), , drop = FALSE]
  sp <- sp[!grepl("^[0-9 ]+$", sp$txt), , drop = FALSE]
  sp$key <- .name_key(sp$txt)
  sp$lkey <- .name_key(sp$txt, local = TRUE)
  sp
}

# Lookup tables for addresses (built once).
.addr_tables <- function() {
  if (!is.null(.cache$addr)) return(.cache$addr)
  first_name <- function(level, names) {
    tab <- .lookup(level)$tab
    tab <- tab[!duplicated(tab$key), ]
    stats::setNames(names[tab$id], tab$key)
  }
  th <- .tab_thanas
  lk <- .lookup("thana")$tab
  lk <- lk[lk$kind != "sadar", ]
  pc <- .tab_postcodes
  pc$po_key <- .name_key(pc$post_office, post = TRUE)
  whole <- which(th$type != "within")
  pc$thana_id <- whole[match(paste(pc$district, pc$thana),
                             paste(th$district, th$thana)[whole])]
  out <- list(district = first_name("district", .tab_districts$district),
              division = first_name("division", .tab_divisions$division),
              thana_ids = lapply(split(lk$id, lk$key), unique),
              pc = pc)
  .cache$addr <- out
  out
}

# 1. Post code: a known 4-digit post code. When there are several, prefer one
# after a word such as "code" or at the end of the address.
.find_postcode <- function(w, t) {
  num <- which(grepl("^[0-9]{4}$", w) & w %in% t$pc$postcode)
  if (!length(num)) return(NULL)
  prev <- c("", w)[num]
  marked <- num[prev %in% .postcode_words | num == length(w)]
  k <- if (length(marked)) marked[length(marked)] else num[length(num)]
  t$pc[t$pc$postcode == w[k], ][1L, ]
}

# 2. Place names: one hit per word sequence that names a district,
# division or thana.
.find_places <- function(w, sp, t) {
  n <- length(w)
  hits <- list()
  add <- function(...) hits[[length(hits) + 1L]] <<- list(...)
  for (r in seq_len(nrow(sp))) {
    s <- sp$s[r]
    e <- sp$e[r]
    key <- sp$key[r]
    lkey <- sp$lkey[r]
    nxt <- if (e < n) w[e + 1L] else ""
    if (nxt %in% .street_words) next
    is_div <- nxt %in% .division_words || any(w[s:e] %in% .division_words)
    if (!is.na(key) && nchar(key) >= 3L) {
      if (!is_div && !is.na(t$district[key])) {
        add(kind = "district", s = s, e = e, value = unname(t$district[key]))
      }
      if (is_div && !is.na(t$division[key])) {
        add(kind = "division", s = s, e = e, value = unname(t$division[key]))
      }
    }
    if (!is.na(lkey) && nchar(lkey) >= .fuzzy_min_target && length(t$thana_ids[[lkey]])) {
      add(kind = "thana", s = s, e = e, ids = t$thana_ids[[lkey]])
    }
    if (s == e && w[s] == "sadar") add(kind = "sadar", s = s, e = e)
  }
  # A shorter hit inside a longer hit of the same kind is dropped
  # ("cox s bazar" is the district, not a "bazar" part).
  inside <- vapply(hits, function(h) any(vapply(hits, function(g) {
    g$kind == h$kind && g$s <= h$s && g$e >= h$e && (g$e - g$s) > (h$e - h$s)
  }, TRUE)), TRUE)
  hits <- hits[!inside]
  # In the order they are written, so that "the last one named" is last.
  hits[order(vapply(hits, `[[`, 0, "s"), vapply(hits, `[[`, 0, "e"))]
}

# 3. Post office after "P.O." when there is no post code.
.find_post_office <- function(w, t) {
  n <- length(w)
  for (p in which(w %in% .post_office_words)) {
    for (len in 3:1) {
      if (p + len > n) next
      name <- paste(w[(p + 1L):(p + len)], collapse = " ")
      k <- .name_key(name)
      r <- t$pc[!is.na(k) & t$pc$po_key %in% k, ]
      if (nrow(r) == 1L) {
        attr(r, "note") <- paste0("post code from the post office name \"", name, "\"")
        return(r)
      }
    }
  }
  NULL
}

.thana_districts <- function(h) unique(.tab_thanas$district[h$ids])
.same_span <- function(a, b) a$s == b$s && a$e == b$e

# 4. District: the best-scoring district name, else the only district of the
# thana names, else the district of the post code.
.pick_district <- function(dh, th_hits, pc_dist) {
  note <- character(0)
  dist <- NA_character_
  if (length(dh)) {
    cand <- unique(vapply(dh, `[[`, "", "value"))
    last_e <- max(vapply(dh, `[[`, 0, "e"))
    score <- vapply(cand, function(d) {
      own <- dh[vapply(dh, function(h) h$value == d, TRUE)]
      th_elsewhere <- any(vapply(th_hits, function(h) d %in% .thana_districts(h) &&
                                   !any(vapply(own, .same_span, TRUE, b = h)), TRUE))
      last <- max(vapply(own, `[[`, 0, "e")) == last_e
      is_th <- any(vapply(th_hits, function(h) any(vapply(own, .same_span, TRUE, b = h)) &&
                            any(.thana_districts(h) %in% setdiff(cand, d)), TRUE))
      .score_thana * th_elsewhere + .score_postcode * isTRUE(pc_dist == d) +
        .score_last * last + .score_is_thana * is_th
    }, 0)
    dist <- cand[which.max(score)]
    if (length(cand) > 1L) {
      note <- paste0("several district names (", paste(cand, collapse = ", "), "); used ", dist)
    }
  }
  own_span <- function(h) any(vapply(dh, function(d) d$value == dist && .same_span(d, h), TRUE))
  th2 <- Filter(function(h) is.na(dist) || !own_span(h), th_hits)
  if (is.na(dist) && length(th2)) {
    ds <- unique(unlist(lapply(th2, .thana_districts)))
    if (length(ds) == 1L) {
      dist <- ds
      note <- c(note, "district from the thana name")
    } else if (!is.na(pc_dist) && pc_dist %in% ds) {
      dist <- pc_dist
      note <- c(note, "district from the post code")
    }
  }
  if (is.na(dist) && !is.na(pc_dist)) {
    dist <- pc_dist
    note <- c(note, "district from the post code only")
  }
  list(district = dist, thana_hits = th2, note = note)
}

# 5. Thana inside the district: the last one named, else "Sadar", else the
# thana of the post code.
.pick_thana <- function(dist, th2, has_sadar, pc_row) {
  th <- .tab_thanas
  note <- character(0)
  id <- NA_integer_
  if (is.na(dist)) {
    if (length(th2)) {
      ids <- unique(unlist(lapply(th2, `[[`, "ids")))
      note <- paste0("thana name used in several districts: ",
                     .fmt_places(th$thana[ids], th$district[ids]))
    }
    return(list(id = id, note = note, ambiguous = length(th2) > 0L))
  }
  ins <- Filter(function(h) dist %in% .thana_districts(h), th2)
  if (length(ins)) {
    ids_in <- vapply(ins, function(h) h$ids[th$district[h$ids] == dist][1L], 1L)
    id <- ids_in[length(ids_in)]
    # A thana inside the area of another thana that is named too
    # ("Ashulia, Savar" or "Savar, Ashulia"): the smaller one is meant.
    inner <- ids_in[th$type[ids_in] == "within" & th$area[ids_in] %in% th$thana[ids_in]]
    if (length(inner)) id <- inner[length(inner)]
  } else if (has_sadar) {
    j <- which(th$district == dist & th$type == "rural" & grepl(" Sadar$", th$thana))
    if (length(j) == 1L) id <- j
  }
  if (is.na(id) && length(th2)) {
    # Village names often equal thana names elsewhere, so this is a note.
    ids <- unique(unlist(lapply(th2, `[[`, "ids")))
    note <- c(note, paste0("names a thana of another district: ",
                           .fmt_places(th$thana[ids], th$district[ids])))
  }
  if (is.na(id) && !is.null(pc_row) && !is.na(pc_row$thana_id) &&
      isTRUE(pc_row$district == dist)) {
    id <- pc_row$thana_id
    note <- c(note, "thana from the post code")
  }
  list(id = id, note = note, ambiguous = FALSE)
}

# One address. `w` its words, `sp` its word sequences that name a place,
# `hint` the district given by the user (or NA).
.read_address <- function(addr, w, sp, hint, t) {
  res <- list(postcode = NA_character_, post_office = NA_character_,
              thana = NA_character_, district = NA_character_, division = NA_character_,
              status = "not found", note = character(0))
  if (is.na(addr) || !length(w)) {
    res$status <- "missing"
    return(res)
  }
  pc_row <- .find_postcode(w, t)
  hits <- .find_places(w, sp, t)
  kinds <- vapply(hits, `[[`, "", "kind")
  if (is.null(pc_row)) {
    pc_row <- .find_post_office(w, t)
    if (!is.null(pc_row)) res$note <- c(res$note, attr(pc_row, "note"))
  }
  if (!is.null(pc_row)) {
    res$postcode <- pc_row$postcode
    res$post_office <- pc_row$post_office
  }
  pc_dist <- if (is.null(pc_row)) NA_character_ else pc_row$district

  dh <- hits[kinds == "district"]
  d <- .pick_district(dh, hits[kinds == "thana"], pc_dist)
  dist <- d$district
  res$note <- c(res$note, d$note)
  th2 <- d$thana_hits
  if (!is.na(hint)) {
    # District names that are also a thana of the given district
    # ("Faridpur" in Pabna) do not contradict it.
    th_in_hint <- Filter(function(h) hint %in% .thana_districts(h), hits[kinds == "thana"])
    dh_other <- Filter(function(g) !any(vapply(th_in_hint, .same_span, TRUE, a = g)), dh)
    named <- unique(vapply(dh_other, `[[`, "", "value"))
    if (length(named) && !hint %in% named) {
      res$note <- c(res$note, paste0("the address names ", paste(named, collapse = ", "),
                                     ", but the district given is ", hint))
      res$status <- "conflict"
    }
    if (!isTRUE(dist == hint)) {
      dist <- hint
      th2 <- Filter(function(h) !any(vapply(dh, function(g) g$value == hint &&
                                               .same_span(g, h), TRUE)), hits[kinds == "thana"])
    }
  }
  p <- .pick_thana(dist, th2, any(kinds == "sadar"), pc_row)
  res$note <- c(res$note, p$note)
  if (p$ambiguous) res$status <- "ambiguous"
  if (!is.na(p$id)) {
    res$thana <- .tab_thanas$thana[p$id]
  }

  # 6. Division and consistency.
  vh <- hits[kinds == "division"]
  if (!is.na(dist)) {
    res$district <- dist
    res$division <- .tab_districts$division[match(dist, .tab_districts$district)]
    if (length(vh) && vh[[length(vh)]]$value != res$division) {
      res$note <- c(res$note, paste0("the address names ", vh[[length(vh)]]$value,
                                     " division, but ", dist, " is in ", res$division))
      res$status <- "conflict"
    }
  } else if (length(vh)) {
    res$division <- vh[[length(vh)]]$value
  }
  if (!is.na(pc_dist) && !is.na(dist) && pc_dist != dist) {
    res$note <- c(res$note, paste0("post code ", res$postcode, " (", res$post_office,
                                   ") is in ", pc_dist, ", not ", dist))
    res$status <- "conflict"
  }
  if (res$status == "not found") {
    res$status <- if (!is.na(p$id)) "complete" else if (!is.na(dist)) "district only" else
      if (!is.na(res$division)) "division only" else "not found"
  }
  res
}

bd_address <- function(x, district = NULL) {
  input <- .as_utf8_chr(x)
  hint <- .district_arg(district, length(input))
  if (is.null(hint)) hint <- rep(NA_character_, length(input))
  combo <- paste(input, hint, sep = "\r")
  first <- which(!duplicated(combo))
  ux <- input[first]
  words <- .addr_words(ux)
  # Missing-value markers ("N/A", "-") are missing addresses.
  words[is.na(ux) | is.na(bd_missing(ux))] <- list(character(0))
  t <- .addr_tables()
  sp <- .addr_spans(words)
  # Only word sequences that can name a place are looked at further.
  keep <- (!is.na(sp$key) & (sp$key %in% names(t$district) | sp$key %in% names(t$division))) |
    (!is.na(sp$lkey) & sp$lkey %in% names(t$thana_ids)) | sp$txt == "sadar"
  by_addr <- split(sp[keep, , drop = FALSE], factor(sp$a[keep], levels = seq_along(ux)))
  r <- lapply(seq_along(ux), function(k) {
    .read_address(ux[k], words[[k]], by_addr[[k]], hint[first[k]], t)
  })
  get <- function(field) vapply(r, `[[`, "", field)
  out <- data.frame(
    input = ux,
    postcode = get("postcode"), post_office = get("post_office"),
    thana = get("thana"),
    district = get("district"), division = get("division"),
    status = get("status"),
    note = vapply(r, function(z) if (length(z$note)) paste(z$note, collapse = "; ") else NA_character_, ""),
    stringsAsFactors = FALSE
  )
  out <- out[match(combo, combo[first]), , drop = FALSE]
  out$input <- input
  .as_tbl(out)
}

# ---- amount.R --------------------------------------------------------------
# Money amounts ---------------------------------------------------------------

# Units recognised in money amounts. Bangla words are written as escapes:
# koti = \u0995\u09cb\u099f\u09bf, lakh = \u09b2\u09be\u0996,
# lokkho = \u09b2\u0995\u09cd\u09b7, hajar = \u09b9\u09be\u099c\u09be\u09b0.
.amount_units <- data.frame(
  pattern = c(
    "crores?|cr|koti|\u0995\u09cb\u099f\u09bf",
    "billions?|bn",
    "millions?|mn",
    "lakhs?|lacs?|lk|\u09b2\u09be\u0996|\u09b2\u0995\u09cd\u09b7",
    "thousands?|hajar|hazar|k|\u09b9\u09be\u099c\u09be\u09b0"
  ),
  # Units are powers of ten. The value is built as text such as "1.1e5" and
  # parsed once, which gives the nearest double to the exact amount;
  # multiplying 1.1 * 1e5 would give 110000.00000000001 instead.
  exponent = c(7L, 9L, 6L, 5L, 3L),
  stringsAsFactors = FALSE
)

.amount_unit_regex <- paste0(
  "(", paste(.amount_units$pattern, collapse = "|"), ")(?![a-z])"
)
.amount_number_regex <- "([-+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+))"
.amount_token_regex <- paste0(.amount_number_regex, " ?(?:", .amount_unit_regex, ")?")

# Currency markers removed before parsing: the taka sign (U+09F3), Tk, BDT,
# taka, the Bangla word taka (\u099f\u09be\u0995\u09be), the endings "/-" and
# "/=", "only", and the Bangla word for only (\u09ae\u09be\u09a4\u09cd\u09b0).
.amount_currency_regex <- paste0(
  "\u09f3|(?<![a-z])(?:tk[.]?|bdt|taka|only)(?![a-z])|",
  "\u099f\u09be\u0995\u09be|\u09ae\u09be\u09a4\u09cd\u09b0|/[-=]"
)

# Power of ten for each unit ("" means no unit, exponent 0).
.unit_exponent <- function(unit) {
  out <- integer(length(unit))
  for (i in seq_len(nrow(.amount_units))) {
    hit <- unit != "" & grepl(paste0("^(?:", .amount_units$pattern[i], ")$"),
                              unit, perl = TRUE)
    out[hit] <- .amount_units$exponent[i]
  }
  out
}

# Exact value of a number written as text times 10^exponent.
.scale_number <- function(num, exponent) {
  as.numeric(paste0(num, "e", exponent))
}

.parse_one_amount <- function(s) {
  if (is.na(s) || s == "") {
    return(NA_real_)
  }
  if (!grepl(paste0("^(?:", .amount_token_regex, " ?)+$"), s, perl = TRUE)) {
    return(NA_real_)
  }
  tokens <- regmatches(s, gregexpr(.amount_token_regex, s, perl = TRUE))[[1]]
  parts <- regmatches(tokens, regexec(paste0("^", .amount_token_regex, "$"),
                                      tokens, perl = TRUE))
  num <- vapply(parts, function(p) p[2L], character(1))
  unit <- vapply(parts, function(p) p[3L], character(1))
  unit[is.na(unit)] <- ""
  n <- length(tokens)
  if (n > 1L) {
    # "1 crore 25 lakh" is fine; "100 200", "25 lakh 1 crore" are not.
    if (any(unit[-n] == "")) return(NA_real_)
    if (any(grepl("^[-+]", num[-1L]))) return(NA_real_)
    if (any(diff(.unit_exponent(unit)) >= 0)) return(NA_real_)
  }
  value <- abs(.scale_number(num, .unit_exponent(unit)))
  total <- if (n > 1L && any(value[-1L] >= 10^.unit_exponent(unit)[-n])) NA_real_ else sum(value)
  if (grepl("^-", num[1L])) -total else total
}

# Exact amounts (single values only; ranges and approximate values give NA).
.parse_amount <- function(x) {
  s <- tolower(.bn_compose(.bn2en(x)))
  # A hyphen or dash right after the currency is a separator, not a minus
  # sign: "BDT-500", "Tk.-500", "Tk - 500" are 500. A real minus sign
  # (U+2212) and a sign before the currency ("-Tk 500") stay negative.
  s <- gsub("(\u09f3|(?<![a-z])(?:tk[.]?|bdt|taka))\\s*[-\u2010-\u2014\uff0d]\\s*(?=[0-9.])",
            "\\1 ", s, perl = TRUE)
  s <- .ascii_signs(s)
  s <- gsub(.amount_currency_regex, " ", s, perl = TRUE)
  s <- .squish(.ungroup_digits(s))
  # Punctuation that ends a sentence carries no value: "5 lakh.", "500 taka<danda>"
  s <- .squish(sub("[\u0964.,;:!?]+$", "", s, perl = TRUE))
  # A sign written before the currency ("-Tk 500") is now separated from
  # the number by a space; join them again.
  s <- sub("^([-+]) (?=[0-9.])", "\\1", s, perl = TRUE)
  # Parse each distinct value once; survey columns repeat values a lot.
  u <- unique(s)
  val <- rep(NA_real_, length(u))
  # Fast vectorised path: a single number with an optional unit.
  single <- paste0("^", .amount_token_regex, "$")
  one <- !is.na(u) & grepl(single, u, perl = TRUE)
  if (any(one)) {
    num <- sub(single, "\\1", u[one], perl = TRUE)
    unit <- sub(single, "\\2", u[one], perl = TRUE)
    val[one] <- .scale_number(num, .unit_exponent(unit))
  }
  # Slow path only for possible combined amounts such as "1 crore 25 lakh":
  # at least two numbers and no comma left over from wrong digit grouping.
  multi <- which(!one & !is.na(u) & !grepl(",", u, fixed = TRUE) &
                   grepl("[0-9][^0-9.]+[-+.]?[0-9]", u, perl = TRUE))
  if (length(multi)) {
    val[multi] <- vapply(u[multi], .parse_one_amount, numeric(1), USE.NAMES = FALSE)
  }
  val[match(s, u)]
}

# Words that mark an approximate amount: about, approx(imately), around,
# roughly, nearly, almost, "~", and the Bangla words praay and anumanik.
.rough_regex <- paste0(
  "(?i)(?<![a-z])(?:approx(?:imately)?[.]?|about|around|roughly|nearly|almost|apx)(?![a-z])|",
  "[~\u2248]|\u09aa\u09cd\u09b0\u09be(?:\u09af\u09bc|\u09df)|\u0986\u09a8\u09c1\u09ae\u09be\u09a8\u09bf\u0995"
)
# A range: two parts with a number each, joined by a dash, "to" or the Bangla
# word theke ("from").
.range_regex <- paste0("^(.*[0-9].*?)\\s*(?:\\p{Pd}|\u2212|(?<![a-z])to(?![a-z])|",
                       "\u09a5\u09c7\u0995\u09c7)\\s*(.*[0-9].*)$")

# A time period after an amount ("per month", "monthly", the Bangla word
# mase): it does not change the amount, so it is removed and noted.
.period_regex <- paste0(
  "(?i)\\s*(?:(?:per|a|/|each|every)\\s*(?:month|mon|mo|year|yr|annum|week|day)|",
  "monthly|yearly|annually|weekly|daily|\u09aa\u09cd\u09b0\u09a4\u09bf\\s*\u09ae\u09be\u09b8\u09c7|",
  "\u09ae\u09be\u09b8\u09bf\u0995|\u09ae\u09be\u09b8\u09c7)\\s*[.]?\\s*$")

# Remove a time period at the end; returns the text and what was removed.
.drop_period <- function(s) {
  has <- !is.na(s) & grepl(.period_regex, s, perl = TRUE)
  what <- rep(NA_character_, length(s))
  if (any(has)) {
    what[has] <- .squish(regmatches(s[has], regexpr(.period_regex, s[has], perl = TRUE)))
    s[has] <- sub(.period_regex, "", s[has], perl = TRUE)
  }
  list(s = s, what = what)
}

# The unit written in a piece of text ("" if none).
.unit_of <- function(t) {
  t <- tolower(.bn_compose(t))
  m <- regmatches(t, regexpr(.amount_unit_regex, t, perl = TRUE))
  if (length(m)) m else ""
}

# Why an amount could not be read.
.amount_reason <- function(x) {
  s <- tolower(.bn2en(x))
  out <- rep("not an amount", length(s))
  out[!grepl("[0-9]", s)] <- "no number"
  out[grepl("[0-9],[0-9]", s) &
        is.na(bd_number(gsub("[^0-9,]", "", s), warn = FALSE))] <- "commas in unusual places"
  out[grepl(paste0("[0-9] ?(?:", .amount_unit_regex, ") ?[0-9]"), s, perl = TRUE)] <-
    "parts that do not add up (for example 12 hajar 1335)"
  out
}

# Amounts as ranges: low, high, approximate and a note for each value.
.amount_details <- function(input) {
  n <- length(input)
  note <- rep(NA_character_, n)
  per <- .drop_period(input)
  rough <- !is.na(per$s) & grepl(.rough_regex, per$s, perl = TRUE)
  s <- per$s
  s[rough] <- .squish(gsub(.rough_regex, " ", s[rough], perl = TRUE))
  single <- .parse_amount(s)
  low <- high <- single
  s_en <- .bn2en(s)
  try <- which(is.na(single) & !is.na(s_en) &
                 grepl(.range_regex, s_en, perl = TRUE, ignore.case = TRUE))
  for (i in try) {
    lo_t <- sub(.range_regex, "\\1", s_en[i], perl = TRUE, ignore.case = TRUE)
    hi_t <- sub(.range_regex, "\\2", s_en[i], perl = TRUE, ignore.case = TRUE)
    lo <- .parse_amount(lo_t)
    hi <- .parse_amount(hi_t)
    # "15-20k": a unit only at the upper end is meant for both ends.
    uh <- .unit_of(hi_t)
    if (!is.na(lo) && !is.na(hi) && .unit_of(lo_t) == "" && uh != "") {
      lo2 <- .parse_amount(paste(lo_t, uh))
      if (!is.na(lo2) && lo2 < hi) {
        lo <- lo2
        note[i] <- "unit of the upper end used for both ends"
      }
    }
    if (!is.na(lo) && !is.na(hi) && lo < hi) {
      low[i] <- lo
      high[i] <- hi
      note[i] <- if (is.na(note[i])) "a range" else paste0("a range; ", note[i])
    } else if (!is.na(lo) && !is.na(hi)) {
      note[i] <- "range with the lower end not below the upper end"
    }
  }
  approx <- rough & !is.na(low)
  note[approx] <- ifelse(is.na(note[approx]), "approximate", paste0("approximate; ", note[approx]))
  bad <- is.na(low) & .nonblank(input) & is.na(note)
  note[bad] <- .amount_reason(s[bad])
  pn <- !is.na(per$what) & !is.na(low)
  note[pn] <- ifelse(is.na(note[pn]), paste0("\"", per$what[pn], "\" ignored"),
                     paste0(note[pn], "; \"", per$what[pn], "\" ignored"))
  exact <- ifelse(!is.na(low) & low == high & !approx, low, NA_real_)
  data.frame(input = input, amount = exact, low = low, high = high,
             approximate = ifelse(.nonblank(input), approx, NA), note = note,
             stringsAsFactors = FALSE)
}

bd_amount <- function(x, details = FALSE, warn = TRUE) {
  .check_flag(details, "details")
  .check_flag(warn, "warn")
  input <- .as_utf8_chr(x)
  if (!details) {
    out <- .parse_amount(.drop_period(input)$s)
    .warn_invalid(sum(is.na(out) & .nonblank(input)), "read as exact amounts", warn)
    return(out)
  }
  d <- .amount_details(input)
  .warn_invalid(sum(is.na(d$low) & .nonblank(input)), "read as amounts", warn)
  .as_tbl(d)
}

bd_taka <- function(x, digits = 0, prefix = "", suffix = "", bangla = FALSE) {
  if (!is.numeric(x)) {
    stop("`x` must be numeric.", call. = FALSE)
  }
  if (!is.numeric(digits) || length(digits) != 1L || is.na(digits) ||
      digits < 0 || digits != round(digits)) {
    stop("`digits` must be a single non-negative whole number.", call. = FALSE)
  }
  if (!is.character(prefix) || length(prefix) != 1L ||
      !is.character(suffix) || length(suffix) != 1L) {
    stop("`prefix` and `suffix` must be single strings.", call. = FALSE)
  }
  .check_flag(bangla, "bangla")
  ok <- is.finite(x)
  out <- rep(NA_character_, length(x))
  if (any(ok)) {
    v <- x[ok]
    txt <- formatC(abs(v), format = "f", digits = digits, big.mark = "")
    int <- sub("[.].*$", "", txt)
    frac <- ifelse(grepl("[.]", txt), sub("^[^.]*", "", txt), "")
    long <- nchar(int) > 3L
    head <- substr(int[long], 1L, nchar(int[long]) - 3L)
    tail <- substr(int[long], nchar(int[long]) - 2L, nchar(int[long]))
    head <- gsub("([0-9])(?=([0-9]{2})+$)", "\\1,", head, perl = TRUE)
    int[long] <- paste0(head, ",", tail)
    neg <- v < 0 & grepl("[1-9]", txt)
    out[ok] <- paste0(ifelse(neg, "-", ""), prefix, int, frac, suffix)
  }
  if (bangla) {
    out <- chartr(.en_digits, .bn_digits, out)
  }
  out
}

# ---- check.R ---------------------------------------------------------------
# Checking and cleaning whole data frames -------------------------------------

.spec_types <- c("phone", "amount", "number", "district", "division", "thana", "address")

.validate_spec <- function(data, spec) {
  if (!is.data.frame(data)) stop("`data` must be a data frame.", call. = FALSE)
  if (is.list(spec)) spec <- unlist(spec)
  if (!is.character(spec) || is.null(names(spec)) || any(names(spec) == "")) {
    stop("`spec` must be a named character vector, for example ",
         "c(mobile = \"phone\", zila = \"district\").", call. = FALSE)
  }
  if (anyDuplicated(names(spec))) {
    stop("Each column may appear only once in `spec`. Duplicated: ",
         paste(unique(names(spec)[duplicated(names(spec))]), collapse = ", "), call. = FALSE)
  }
  missing_cols <- setdiff(names(spec), names(data))
  if (length(missing_cols)) {
    stop("Column(s) not found in `data`: ", paste(missing_cols, collapse = ", "), call. = FALSE)
  }
  bad <- setdiff(unique(spec), .spec_types)
  if (length(bad)) {
    stop("Unknown type(s) in `spec`: ", paste(bad, collapse = ", "), ". Use one of: ",
         paste(.spec_types, collapse = ", "), ".",
         if ("upazila" %in% bad) " Upazila names are cleaned with type \"thana\".",
         call. = FALSE)
  }
  spec
}

# Standard district names from the column named by `district`, or NULL.
.district_column <- function(data, district) {
  if (is.null(district)) return(NULL)
  if (!is.character(district) || length(district) != 1L || !district %in% names(data)) {
    stop("`district` must be the name of one column in `data`.", call. = FALSE)
  }
  # Read the district names once (one warning for names that cannot be read).
  .district_arg(bd_missing(data[[district]]), nrow(data))
}

# Clean one column. Returns a list: `value` (the main result, NA where the
# value could not be read), `extra` (more columns, named by their suffix) and
# `reason` (why each value could not be read; NA where it could).
.clean_one <- function(x, type, dist, phone_format = "local", style = "current",
                       fuzzy = TRUE, report = "none", label = NULL) {
  if (type == "phone") {
    d <- bd_phone(x, format = phone_format, details = TRUE, warn = FALSE)
    return(list(value = d$phone, extra = NULL, reason = d$note))
  }
  if (type == "amount") {
    d <- bd_amount(x, details = TRUE, warn = FALSE)
    return(list(value = d$amount, extra = NULL, reason = d$note))
  }
  if (type == "number") {
    v <- bd_number(x, warn = FALSE)
    return(list(value = v, extra = NULL, reason = ifelse(is.na(v), "not a plain number", NA)))
  }
  if (type == "address") {
    d <- bd_address(x, district = dist)
    ok <- !is.na(d$district) & d$status != "conflict"
    extra <- list(postcode = d$postcode, thana = d$thana,
                  district = d$district, division = d$division, status = d$status)
    reason <- ifelse(ok, NA_character_,
                     ifelse(is.na(d$note), d$status, paste0(d$status, ": ", d$note)))
    return(list(value = NULL, extra = extra, reason = reason, ok = ok))
  }
  # district, division, thana
  if (type != "thana") dist <- NULL
  if (type == "thana" && style == "bangla") style <- "current"
  d <- bd_place(x, level = type, district = dist, style = style, fuzzy = fuzzy,
                details = TRUE, report = "none", warn = FALSE)
  value <- d[[type]]
  how <- ifelse(d$match %in% c("exact", "code", "ambiguous"), NA_character_,
                ifelse(d$matched_as %in% "Sadar + district", "sadar", d$matched_as))
  .report_changes(x, value, how, type, report, label)
  if (type == "thana" && style %in% c("map", "legacy") && report != "none") {
    .report_map_areas(.match_names(x, "thana", dist, fuzzy)$id, value)
  }
  why <- if (type == "thana") d$note else d$candidates
  fail <- is.na(value) & .nonblank(x)
  reason <- rep(NA_character_, length(value))
  reason[fail] <- paste("not a", type, "name")
  reason[fail & d$match == "ambiguous"] <- paste("ambiguous:", why[fail & d$match == "ambiguous"])
  reason[fail & d$match %in% c("exact", "variant", "typing error", "code")] <-
    paste0("no ", style, " spelling of this ", type)
  if (!is.null(dist)) {
    reason[fail & d$match == "not found" & .nonblank(dist)] <-
      paste("not a", type, "of the district given")
  }
  extra <- NULL
  list(value = value, extra = extra, reason = reason)
}

bd_check <- function(data, spec, details = FALSE, district = NULL, id = NULL,
                     markers = NULL, fuzzy = TRUE) {
  spec <- .validate_spec(data, spec)
  .check_flag(details, "details")
  .check_flag(fuzzy, "fuzzy")
  if (!is.null(id) && (!is.character(id) || length(id) != 1L || !id %in% names(data))) {
    stop("`id` must be the name of one column in `data`.", call. = FALSE)
  }
  dist <- .district_column(data, district)
  rows <- lapply(names(spec), function(col) {
    x <- bd_missing(data[[col]], markers = markers)
    present <- .nonblank(x)
    r <- .clean_one(x, spec[[col]], dist, fuzzy = fuzzy)
    ok <- if (!is.null(r$ok)) r$ok else !is.na(r$value)
    invalid <- present & !ok
    if (details) {
      bad <- which(invalid)
      out <- data.frame(row = bad, column = rep(col, length(bad)),
                        type = rep(spec[[col]], length(bad)),
                        value = .as_utf8_chr(data[[col]])[bad], reason = r$reason[bad],
                        stringsAsFactors = FALSE)
      if (!is.null(id)) out <- data.frame(id = data[[id]][bad], out, stringsAsFactors = FALSE)
      return(out)
    }
    data.frame(
      column = col, type = spec[[col]], n = length(x),
      n_missing = sum(!present), n_valid = sum(present & ok), n_invalid = sum(invalid),
      pct_valid = if (any(present)) round(100 * sum(present & ok) / sum(present), 1) else NA_real_,
      invalid_examples = paste(utils::head(unique(.as_utf8_chr(x)[invalid]), 3L), collapse = "; "),
      stringsAsFactors = FALSE)
  })
  .as_tbl(do.call(rbind, rows))
}

bd_clean <- function(data, spec, district = NULL, suffix = "_clean",
                     phone_format = c("local", "e164", "international"),
                     style = c("current", "legacy", "bangla", "map"), fuzzy = TRUE,
                     report = c("fixes", "all", "none"), markers = NULL) {
  spec <- .validate_spec(data, spec)
  phone_format <- match.arg(phone_format)
  style <- match.arg(style)
  report <- match.arg(report)
  .check_flag(fuzzy, "fuzzy")
  if (!is.character(suffix) || length(suffix) != 1L || is.na(suffix)) {
    stop("`suffix` must be a single string.", call. = FALSE)
  }
  dist <- .district_column(data, district)
  for (col in names(spec)) {
    x <- bd_missing(data[[col]], markers = markers)
    r <- .clean_one(x, spec[[col]], dist, phone_format, style, fuzzy, report, label = col)
    if (!is.null(r$value)) data[[paste0(col, suffix)]] <- r$value
    for (nm in names(r$extra)) data[[paste0(col, "_", nm)]] <- r$extra[[nm]]
  }
  data
}

# ---- digits.R --------------------------------------------------------------
bd_digits <- function(x, to = c("en", "bn")) {
  to <- match.arg(to)
  x <- .as_utf8_chr(x)
  if (to == "en") chartr(.bn_digits, .en_digits, x) else chartr(.en_digits, .bn_digits, x)
}

bd_number <- function(x, warn = TRUE) {
  .check_flag(warn, "warn")
  s <- .ungroup_digits(.squish(.ascii_signs(.bn2en(x))))
  ok <- !is.na(s) & grepl("^[-+]?([0-9]+([.][0-9]*)?|[.][0-9]+)$", s, perl = TRUE)
  out <- rep(NA_real_, length(s))
  out[ok] <- as.numeric(s[ok])
  .warn_invalid(sum(!ok & !is.na(s) & s != ""), "read as numbers", warn)
  out
}

# ---- missing.R -------------------------------------------------------------
bd_squish <- function(x, strip_quotes = FALSE) {
  .check_flag(strip_quotes, "strip_quotes")
  .squish(.as_utf8_chr(x), strip_quotes = strip_quotes)
}

bd_missing <- function(x, extra = NULL, markers = NULL, blank = TRUE) {
  .check_flag(blank, "blank")
  if (!is.null(markers) && !is.character(markers) || !is.null(extra) && !is.character(extra)) {
    stop("`markers` and `extra` must be character vectors.", call. = FALSE)
  }
  if (is.null(markers)) markers <- .tab_na_words
  key <- function(v) tolower(.bn_key(.squish(.as_utf8_chr(v))))
  hit <- key(x) %in% key(c(markers, extra))
  if (blank) hit <- hit | !.nonblank(x)
  hit <- hit & !is.na(x)
  if (is.factor(x)) {
    x[hit] <- NA
    return(droplevels(x, exclude = NA))
  }
  x[hit] <- NA
  x
}

# ---- names.R ---------------------------------------------------------------
# Place-name matching shared by bd_place(), bd_address() and bd_clean() -----
#
# Steps for every level (district, division, thana):
#   1. .name_key()    reduce a name to a matching key;
#   2. .lookup()      all known spellings of the level, as keys;
#   3. .match_names() exact key match, then (optionally) a careful fuzzy match;
#   4. .report_changes() list the values that were changed, as a message.

# Words removed from every name: "District", "Zila", "Division" and the like.
.admin_words_re <- paste0("(?<![a-z])(district|zila|zilla|zela|dist|division|div|bibhag|",
                          "hill district|city corporation|city corp|city)(?![a-z])")
# Bangla zela (district) and bibhag (division).
.admin_words_bn_re <- "\u099c\u09c7\u09b2\u09be|\u09ac\u09bf\u09ad\u09be\u0997"
# Words removed from thana names: "Thana", "P.S." and also "Upazila", because
# most thanas are written as upazilas ("Savar Upazila").
.local_words_re <- paste0("(?<![a-z])(upazila|upazilla|upozila|upozilla|upojela|upojila|",
                          "thana|police station|p[.]? ?s[.]?|metropolitan)(?![a-z])")
# Bangla upojela and thana.
.local_words_bn_re <- "\u0989\u09aa\u099c\u09c7\u09b2\u09be|\u09a5\u09be\u09a8\u09be"
# Post office types removed from post office names ("Mirpur TSO" -> "mirpur").
.office_words_re <- "(?<![a-z])(gpo|ho|upo|so|tso|edso|edbo|bo|tsc|eddo)(?![a-z])"

# Fuzzy matching limits. Targets shorter than this are matched exactly only:
# abbreviations such as "ctg" would otherwise attract short words ("city").
.fuzzy_min_target <- 4L

.name_key <- function(x, local = FALSE, post = FALSE) {
  s <- tolower(.squish(.as_utf8_chr(x)))
  if (post) s <- gsub(.office_words_re, " ", s, perl = TRUE)
  if (local) {
    s <- gsub(.local_words_re, " ", s, perl = TRUE)
    s <- gsub(.local_words_bn_re, " ", s, perl = TRUE)
  }
  s <- .bn_key(s)
  s <- chartr("\u09a3\u09b7", "\u09a8\u09b8", s)
  # Apostrophes are dropped ("Cox's" -> "coxs"); other punctuation separates
  # words, so "Dhaka-Zila" and "Dhaka(District)" lose the suffix.
  s <- gsub("['\u2019]", "", s, perl = TRUE)
  s <- gsub("[^a-z \u0980-\u09ff]", " ", s, perl = TRUE)
  s <- gsub(.admin_words_re, " ", s, perl = TRUE)
  s <- gsub(.admin_words_bn_re, " ", s, perl = TRUE)
  s <- gsub("[^a-z\u0980-\u09ff]", "", s, perl = TRUE)
  s <- gsub("gonj", "ganj", s, fixed = TRUE)
  s[s == ""] <- NA_character_
  s
}

# Reference table of each level: one row per place, with `name` and
# `district` (NA for divisions). Ids used below are row numbers of it.
.ref <- function(level) {
  switch(level,
    district = data.frame(name = .tab_districts$district, district = .tab_districts$district,
                          stringsAsFactors = FALSE),
    division = data.frame(name = .tab_divisions$division, district = NA_character_,
                          stringsAsFactors = FALSE),
    thana = data.frame(name = .tab_thanas$thana, district = .tab_thanas$district,
                       stringsAsFactors = FALSE))
}

# Cache of the lookup tables (they are built on first use).
.cache <- new.env(parent = emptyenv())

.lookup <- function(level) {
  if (!is.null(.cache[[level]])) return(.cache[[level]])
  tab <- switch(level,
    district = {
      d <- .tab_districts
      id <- seq_len(nrow(d))
      al <- .tab_dist_alias
      data.frame(
        key = .name_key(c(d$district, d$district_legacy, d$district_map, d$district_bn, al$alias)),
        id = c(id, id, id, id, match(al$district, d$district)),
        kind = rep(c("official", "old spelling", "boundary-file spelling", "Bangla", "variant"),
                   c(rep(nrow(d), 4L), nrow(al))),
        stringsAsFactors = FALSE)
    },
    division = {
      v <- .tab_divisions
      id <- seq_len(nrow(v))
      al <- .tab_div_alias
      # Every division is named after its headquarters district, so variant
      # spellings of those districts (for example "Rongpur") apply too.
      hq <- .tab_dist_alias[.tab_dist_alias$district %in% v$division, ]
      data.frame(
        key = .name_key(c(v$division, v$division_legacy, v$division_bn, al$alias, hq$alias)),
        id = c(id, id, id, match(al$division, v$division), match(hq$district, v$division)),
        kind = rep(c("official", "old spelling", "Bangla", "variant", "variant"),
                   c(rep(nrow(v), 3L), nrow(al), nrow(hq))),
        stringsAsFactors = FALSE)
    },
    thana = {
      th <- .tab_thanas
      id <- seq_len(nrow(th))
      al <- .tab_thana_alias
      within <- th$type == "within"
      # A "within" thana has no area of its own in the boundary files; its
      # map name is that of the area it lies in, so it is not a spelling.
      has_map <- th$map_name != "" & !within
      sadar <- th$type == "rural" & grepl(" Sadar$", th$thana)
      leg <- .tab_districts$district_legacy[match(th$district, .tab_districts$district)]
      tab <- data.frame(
        key = .name_key(c(th$thana, th$map_name[has_map], al$alias,
                          paste(leg[sadar], "Sadar"), rep("sadar", sum(sadar))), local = TRUE),
        id = c(id, id[has_map], match(paste(al$district, al$thana), paste(th$district, th$thana)),
               id[sadar], id[sadar]),
        kind = c(rep("official", nrow(th)), rep("boundary-file spelling", sum(has_map)), al$kind,
                 rep("old district spelling", sum(sadar)), rep("sadar", sum(sadar))),
        stringsAsFactors = FALSE)
      # A name of a "within" thana means that thana, even where the post
      # office list uses it for the larger area ("Fatulla").
      own <- tab$key[!is.na(tab$id) & within[tab$id]]
      tab[(!is.na(tab$id) & within[tab$id]) | !tab$key %in% own, ]
    })
  tab <- tab[!is.na(tab$key) & !is.na(tab$id), ]
  # Keep the first (most official) kind for each key and place.
  tab <- tab[!duplicated(paste(tab$key, tab$id)), ]
  rownames(tab) <- NULL
  out <- list(tab = tab, by_key = split(seq_len(nrow(tab)), tab$key))
  .cache[[level]] <- out
  out
}

.fuzzy_pick <- function(key, pool, names, max_distance) {
  pool <- pool[nchar(pool$key) >= .fuzzy_min_target & pool$kind != "sadar", , drop = FALSE]
  if (!nrow(pool)) return(integer(0))
  d <- utils::adist(key, pool$key)[1L, ]
  m <- min(d)
  ids <- unique(pool$id[d == m])
  if (m <= min(max_distance, nchar(key) %/% 3L) && length(unique(names[ids])) == 1L) ids else integer(0)
}

.match_names <- function(x, level, district = NULL, fuzzy = TRUE, max_distance = 2) {
  local <- level == "thana"
  key <- .name_key(x, local = local)
  dist <- if (is.null(district)) rep(NA_character_, length(key)) else district
  lk <- .lookup(level)
  ref <- .ref(level)
  combo <- paste(key, dist, sep = "\r")
  first <- which(!duplicated(combo))
  res <- lapply(first, function(i) {
    k <- key[i]
    d <- dist[i]
    out <- list(id = NA_integer_, match = "not found", how = NA_character_,
                name = NA_character_, candidates = NA_character_)
    if (is.na(k)) {
      if (!.nonblank(x[i])) out$match <- "missing"
      return(out)
    }
    rows <- lk$by_key[[k]]
    hit <- lk$tab[if (is.null(rows)) integer(0) else rows, , drop = FALSE]
    if (!is.na(d)) {
      hit <- hit[ref$district[hit$id] %in% d, , drop = FALSE]
    } else {
      hit <- hit[hit$kind != "sadar", , drop = FALSE]  # "Sadar" alone needs a district
    }
    ids <- unique(hit$id)
    how <- if (nrow(hit)) hit$kind[1L] else NA_character_
    if (!length(ids) && local && k == "sadar" && is.na(d)) {
      out$match <- "ambiguous"
      out$candidates <- "\"Sadar\": give the district"
      return(out)
    }
    if (!length(ids) && fuzzy) {
      pool <- lk$tab
      if (!is.na(d)) pool <- pool[ref$district[pool$id] %in% d, , drop = FALSE]
      ids <- .fuzzy_pick(k, pool, ref$name, max_distance)
      how <- "typing error"
    }
    if (!length(ids)) return(out)
    if (length(unique(ref$name[ids])) == 1L) out$name <- ref$name[ids[1L]]
    if (length(ids) > 1L) {
      out$match <- "ambiguous"
      out$candidates <- .fmt_places(ref$name[ids], ref$district[ids])
      out$how <- how
      return(out)
    }
    out$id <- ids
    out$how <- how
    out$match <- if (how == "official") "exact" else if (how == "typing error") "typing error" else "variant"
    out
  })
  idx <- match(combo, combo[first])
  data.frame(
    id = vapply(res, function(r) as.integer(r$id), 1L)[idx],
    match = vapply(res, `[[`, "", "match")[idx],
    how = vapply(res, `[[`, "", "how")[idx],
    name = vapply(res, `[[`, "", "name")[idx],
    candidates = vapply(res, `[[`, "", "candidates")[idx],
    stringsAsFactors = FALSE
  )
}

# Why each kind of spelling is reported, and which `report` setting lists it.
.change_why <- c(
  "typing error" = "typing error, corrected by fuzzy matching",
  "variant" = "not the standard spelling",
  "postal spelling" = "spelling used by the post office",
  "boundary-file spelling" = "spelling used in boundary (map) files",
  "old district spelling" = "Sadar with the old district spelling",
  "sadar" = "\"Sadar\" read with the district given",
  "old spelling" = "spelling used before 2018",
  "Bangla" = "written in Bangla"
)
.change_fixes <- c("typing error", "variant", "postal spelling", "boundary-file spelling",
                   "old district spelling", "sadar")

.report_changes <- function(input, output, how, level, report, label = NULL) {
  kinds <- switch(report, none = character(0), fixes = .change_fixes,
                  all = names(.change_why))
  typed <- .squish(.as_utf8_chr(input))
  # Values that differ only in case, spaces or a suffix such as "District"
  # are not reported.
  hit <- !is.na(how) & how %in% kinds & !is.na(output) &
    !(.name_key(typed, local = TRUE) %in% .name_key(output, local = TRUE))
  if (!any(hit)) return(invisible(NULL))
  pair <- paste(typed[hit], output[hit], how[hit], sep = "\r")
  first <- !duplicated(pair)
  ch <- data.frame(typed = typed[hit][first], output = output[hit][first],
                   how = how[hit][first], n = tabulate(match(pair, pair[first])),
                   stringsAsFactors = FALSE)
  ch <- ch[order(match(ch$how, names(.change_why)), -ch$n, ch$typed), ]
  lines <- sprintf("  \"%s\" -> \"%s\" (%s%s)", ch$typed, ch$output, .change_why[ch$how],
                   ifelse(ch$n > 1L, paste0("; ", ch$n, " values"), ""))
  if (length(lines) > 20L) {
    lines <- c(lines[1:20], sprintf("  ... and %d more", length(lines) - 20L))
  }
  n <- sum(hit)
  head <- sprintf("%s%d %s %s not written as the standard %s name and %s changed:",
                  if (is.null(label)) "" else paste0(label, ": "), n,
                  if (n == 1L) "value" else "values", if (n == 1L) "was" else "were",
                  level, if (n == 1L) "was" else "were")
  tail <- if (any(ch$how == "typing error")) "Typing-error corrections are guesses: check them by hand."
  message(paste(c(head, lines, tail), collapse = "\n"))
  invisible(NULL)
}

# Standard district names of a `district` argument: NULL, one value for all
# of `x`, or one value per element of `x`.
.district_arg <- function(district, n) {
  if (is.null(district)) return(NULL)
  m <- .match_names(district, "district")
  d <- .tab_districts$district[m$id]
  bad <- .nonblank(district) & is.na(d)
  if (any(bad)) {
    warning(sprintf("%d value%s of `district` could not be matched and %s ignored: %s",
                    sum(bad), if (sum(bad) == 1L) "" else "s",
                    if (sum(bad) == 1L) "was" else "were",
                    paste(utils::head(unique(.squish(.as_utf8_chr(district[bad]))), 5L),
                          collapse = ", ")), call. = FALSE)
  }
  if (length(d) == 1L) d <- rep(d, n)
  if (length(d) != n) {
    stop("`district` must have length 1 or the same length as `x`.", call. = FALSE)
  }
  d
}

# ---- phone.R ---------------------------------------------------------------
# Phone numbers --------------------------------------------------------------

# A Bangladeshi mobile number is 11 digits: 0, then 1, an operator digit
# (3 to 9) and 8 more digits. Before the national number there may be the
# country code (+880, 00880 or 880) and/or the trunk 0.
.phone_pattern <- "^(?:(?:[+]|00)?880)?0?(1[3-9][0-9]{8})$"
.phone_has_prefix <- "^(?:(?:[+]|00)?880|0)"
# Characters people put inside one number: every space and dash, brackets,
# dots, slashes, quotes and invisible characters.
.phone_inside_re <- "[\\s\\p{Zs}\\p{Pd}\u200b\u200c\u200d\ufeff()./\"'\u201c\u201d\u2018\u2019]"
# Separators between two numbers in one cell: / , ; & | "or" and line breaks.
.phone_split_re <- "\\s*(?:/|,|;|&|\\||\\n|(?<![a-z])or(?![a-z]))\\s*"
# A run of digits with the characters allowed inside a number.
.phone_run_re <- "(?:[+]|00)?[0-9](?:[0-9]|[\\s\\p{Pd}.()])*[0-9]"
# One complete number with its 0 or country code, possibly with spaces or
# dashes inside, used to find numbers that are separated only by spaces
# ("01712345678 01812345678").
.phone_strict_re <- "(?<![0-9])(?:(?:[+]|00)?880[\\s-]?|0)1[3-9](?:[\\s-]?[0-9]){8}(?![0-9])"
# +881 followed by a 10-digit mobile number (see `plus881`).
.phone_881_re <- "^(?:[+]|00)?881([3-9][0-9]{8})$"

# The 10-digit national number (1XXXXXXXXX) of each value, or NA.
.phone_core <- function(x, allow_missing_zero = TRUE) {
  s <- .ascii_signs(.bn2en(x))
  # A number stored as text by a spreadsheet can end in ".0" (8801712345678.0).
  s <- sub("^\\s*([+]?[0-9]+)[.]0+\\s*$", "\\1", s, perl = TRUE)
  s <- gsub(.phone_inside_re, "", s, perl = TRUE)
  ok <- !is.na(s) & grepl(.phone_pattern, s, perl = TRUE)
  if (!allow_missing_zero) ok <- ok & grepl(.phone_has_prefix, s, perl = TRUE)
  out <- rep(NA_character_, length(s))
  out[ok] <- sub(.phone_pattern, "\\1", s[ok], perl = TRUE)
  out
}

# Write 10-digit national numbers in the chosen format.
.phone_format <- function(core, format) {
  out <- rep(NA_character_, length(core))
  ok <- !is.na(core)
  out[ok] <- switch(format,
    local = paste0("0", core[ok]),
    e164 = paste0("+880", core[ok]),
    international = paste0("+880 ", substr(core[ok], 1L, 4L), "-", substr(core[ok], 5L, 10L))
  )
  out
}

# Why a value is not a mobile number (one short reason per value).
.phone_reason <- function(x) {
  s <- .ascii_signs(.bn2en(x))
  compact <- gsub("[^0-9+]", "", s)
  core <- sub("^(?:(?:[+]|00)?880|0)", "", compact, perl = TRUE)
  nd <- nchar(gsub("[^0-9]", "", s))
  out <- rep("not a mobile number", length(s))
  out[nd == 0L] <- "no digits"
  out[nd > 0L & nchar(core) < 10L] <- "too few digits"
  out[nchar(core) > 10L] <- "too many digits"
  out[nchar(core) == 10L & !grepl("^1[3-9]", core)] <- "not a mobile prefix (013 to 019)"
  out[grepl("^(?:[+]|00)?881", compact, perl = TRUE)] <-
    "country code +881 (satellite phones); +880 with its 0 missing? See `plus881`"
  out[grepl("^\\s*[0-9][.,][0-9]+\\s*[eE][+]?[0-9]+\\s*$", s)] <-
    "Excel scientific notation: the digits are lost"
  out[is.na(s)] <- NA_character_
  out
}

# Every mobile number in one cell: national numbers and a note.
.phone_find <- function(v, allow_missing_zero, plus881) {
  parts <- strsplit(tolower(.bn2en(v)), .phone_split_re, perl = TRUE)[[1]]
  parts <- parts[nzchar(parts)]
  orig <- parts
  # Keep the digit run of each part, so that words around a number
  # ("phone:", "alt", "(home)") do not matter.
  has <- grepl(.phone_run_re, parts, perl = TRUE)
  parts[has] <- regmatches(parts, regexpr(.phone_run_re, parts, perl = TRUE))
  core <- .phone_core(parts, allow_missing_zero)
  # A part may hold more numbers separated only by spaces or words
  # ("01712345678 01812345678", "Mob 0171... Home 0181..."); every complete
  # number in it is taken too.
  for (i in seq_along(orig)) {
    found <- regmatches(orig[i], gregexpr(.phone_strict_re, orig[i], perl = TRUE))[[1]]
    if (length(found) > 1L || (length(found) && is.na(core[i]))) {
      core <- c(core, .phone_core(found))
    }
  }
  note <- character(0)
  if (plus881) {
    t <- gsub("[^0-9+]", "", .ascii_signs(parts))
    fix <- is.na(core) & grepl(.phone_881_re, t, perl = TRUE)
    if (any(fix)) {
      core[fix] <- paste0("1", sub(.phone_881_re, "\\1", t[fix], perl = TRUE))
      note <- c(note, paste0("read +881 as +880 with the 0 missing: ",
                             paste(orig[fix], collapse = ", ")))
    }
  }
  nums <- unique(core[!is.na(core)])
  if (!length(nums)) note <- c(note, unique(.phone_reason(orig)))
  list(nums = nums, note = if (length(note)) paste(note, collapse = "; ") else NA_character_)
}

bd_phone <- function(x, format = c("local", "e164", "international"), details = FALSE,
                     multiple = c("na", "first"), allow_missing_zero = TRUE,
                     plus881 = FALSE, warn = TRUE) {
  format <- match.arg(format)
  multiple <- match.arg(multiple)
  .check_flag(details, "details")
  .check_flag(allow_missing_zero, "allow_missing_zero")
  .check_flag(plus881, "plus881")
  .check_flag(warn, "warn")
  input <- .as_utf8_chr(x)
  present <- .nonblank(input)

  # Work on the distinct values only; survey columns repeat values.
  u <- unique(input[present])
  core <- .phone_core(u, allow_missing_zero)
  nums <- as.list(core)
  note <- rep(NA_character_, length(u))
  # Values that are not one clean number: look for numbers inside them.
  for (i in which(is.na(core))) {
    f <- .phone_find(u[i], allow_missing_zero, plus881)
    nums[[i]] <- f$nums
    note[i] <- f$note
  }
  n_num <- lengths(nums)
  first <- vapply(nums, function(z) if (length(z)) z[1L] else NA_character_, "")
  chosen <- first
  if (multiple == "na") chosen[n_num > 1L] <- NA_character_
  several <- n_num > 1L
  note[several] <- paste0(n_num[several], " numbers in one cell; ",
                          if (multiple == "na") "phone is NA (see `multiple`)" else "phone is the first",
                          ifelse(is.na(note[several]), "", paste0("; ", note[several])))

  idx <- match(input, u)
  phone <- .phone_format(chosen[idx], format)
  .warn_invalid(sum(present & is.na(first[idx])), "read as mobile numbers", warn)
  if (!details) return(phone)

  all <- vapply(nums, function(z) if (length(z)) paste(.phone_format(z, format), collapse = "; ")
                else NA_character_, "")
  op <- .tab_prefixes$operator[match(paste0("0", substr(chosen, 1L, 2L)), .tab_prefixes$prefix)]
  .as_tbl(data.frame(
    input = input,
    phone = phone,
    valid = ifelse(present, !is.na(first[idx]), NA),
    n_numbers = ifelse(present, n_num[idx], 0L),
    all_numbers = all[idx],
    operator = op[idx],
    note = note[idx],
    stringsAsFactors = FALSE
  ))
}

# ---- place.R ---------------------------------------------------------------
# District, division and thana names --------------------------------------------

# District codes: two-digit BBS codes ("26" or 26), pcodes ("BD3026") and
# ISO 3166-2 codes ("BD-13"). Returns the row of .tab_districts or NA.
.district_code <- function(input) {
  tab <- .tab_districts
  s <- toupper(gsub("[[:space:]]", "", input))
  idx <- rep(NA_integer_, length(s))
  bbs <- !is.na(s) & grepl("^[0-9]{1,2}$", s)
  idx[bbs] <- match(sprintf("%02d", as.integer(s[bbs])), tab$bbs_code)
  pc <- !is.na(s) & grepl("^BD[0-9]{4}$", s)
  idx[pc] <- match(s[pc], tab$pcode)
  iso <- !is.na(s) & grepl("^BD-[0-9]{1,2}$", s)
  idx[iso] <- match(sprintf("BD-%02d", as.integer(sub("BD-", "", s[iso]))), tab$iso_code)
  attr(idx, "is_code") <- bbs | pc | iso
  idx
}

# The name of each matched place in the requested style.
.styled <- function(id, level, style) {
  if (level == "district") {
    col <- switch(style, current = "district", legacy = "district_legacy",
                  bangla = "district_bn", map = "district_map")
    return(.tab_districts[[col]][id])
  }
  if (level == "division") {
    col <- switch(style, current = "division", legacy = , map = "division_legacy",
                  bangla = "division_bn")
    return(.tab_divisions[[col]][id])
  }
  out <- switch(style, current = .tab_thanas$thana[id], bangla = rep(NA_character_, length(id)),
                .tab_thanas$map_name[id])
  out[out %in% ""] <- NA_character_
  out
}

bd_place <- function(x, level = c("district", "division", "thana"),
                     district = NULL, style = c("current", "legacy", "bangla", "map"),
                     fuzzy = TRUE, max_distance = 2, details = FALSE,
                     report = c("fixes", "all", "none"), warn = TRUE) {
  level <- match.arg(level)
  style <- match.arg(style)
  report <- match.arg(report)
  .check_flag(fuzzy, "fuzzy")
  .check_distance(max_distance)
  .check_flag(details, "details")
  .check_flag(warn, "warn")
  if (level == "thana" && style == "bangla") {
    warning("Bangla names of thanas are not in the data yet; style = \"bangla\" gives NA.",
            call. = FALSE)
  }
  input <- .as_utf8_chr(x)
  dist <- if (level == "thana") .district_arg(district, length(input))
  m <- .match_names(input, level, dist, fuzzy, max_distance)

  if (level == "district") {
    code <- .district_code(input)
    is_code <- attr(code, "is_code")
    m$id[is_code] <- code[is_code]
    m$match[is_code] <- ifelse(is.na(code[is_code]), "not found", "code")
    m$how[is_code] <- NA_character_
    m$candidates[is_code] <- NA_character_
  }
  out <- .styled(m$id, level, style)
  .warn_invalid(sum(.nonblank(input) & is.na(m$id)), paste("matched to one", level), warn)
  .report_changes(input, out, m$how, level, report)
  if (level == "thana" && style %in% c("map", "legacy") && report != "none") {
    .report_map_areas(m$id, out)
  }
  if (!details) return(out)

  matched_as <- ifelse(m$how %in% "sadar", "Sadar + district", m$how)
  matched_as[m$match == "ambiguous"] <- NA_character_
  tab <- switch(level,
    district = {
      d <- .tab_districts[m$id, ]
      data.frame(input = input, district = out, division = d$division,
                 bbs_code = d$bbs_code, pcode = d$pcode, iso_code = d$iso_code,
                 stringsAsFactors = FALSE)
    },
    division = {
      v <- .tab_divisions[m$id, ]
      data.frame(input = input, division = out, bbs_code = v$bbs_code,
                 stringsAsFactors = FALSE)
    },
    thana = {
      th <- .tab_thanas[m$id, ]
      blank_na <- function(v) ifelse(v %in% "", NA_character_, v)
      data.frame(input = input, thana = out, district = th$district, division = th$division,
                 type = th$type, map_name = blank_na(th$map_name), pcode = blank_na(th$pcode),
                 stringsAsFactors = FALSE)
    })
  tab$match <- m$match
  tab$matched_as <- matched_as
  tab$candidates <- m$candidates
  if (level == "thana") tab$note <- ifelse(.tab_thanas$note[m$id] %in% "", NA_character_,
                                           .tab_thanas$note[m$id])
  .as_tbl(tab)
}

# Message for "within" thanas written with the map name of the area they lie
# in (style = "map"): Ashulia -> Savar.
.report_map_areas <- function(id, out) {
  w <- !is.na(id) & .tab_thanas$type[id] %in% "within"
  if (!any(w)) return(invisible(NULL))
  pairs <- unique(paste0("  \"", .tab_thanas$thana[id[w]], "\" -> \"", out[w], "\""))
  message(sum(w), if (sum(w) == 1L) " thana has" else " thanas have",
          " no area of its own in the boundary files and ",
          if (sum(w) == 1L) "was" else "were", " given the area it lies in:\n",
          paste(pairs, collapse = "\n"))
  invisible(NULL)
}

# ---- utils.R ---------------------------------------------------------------
# Internal helpers --------------------------------------------------------

# Bengali digits U+09E6 to U+09EF, written with escapes so the source stays ASCII.
.bn_digits <- "\u09e6\u09e7\u09e8\u09e9\u09ea\u09eb\u09ec\u09ed\u09ee\u09ef"
.en_digits <- "0123456789"

# Coerce input to a UTF-8 character vector without losing digits of
# large whole numbers (for example phone numbers stored as numbers).
.as_utf8_chr <- function(x) {
  if (is.factor(x)) {
    x <- as.character(x)
  }
  if (is.numeric(x)) {
    out <- rep(NA_character_, length(x))
    ok <- !is.na(x)
    whole <- ok & is.finite(x) & x == round(x)
    out[whole] <- formatC(x[whole], format = "f", digits = 0, big.mark = "")
    out[ok & !whole] <- format(x[ok & !whole], scientific = FALSE, trim = TRUE,
                               digits = 15)
    return(out)
  }
  if (!is.character(x) && !is.logical(x)) {
    stop("`x` must be a character, numeric or factor vector.", call. = FALSE)
  }
  x <- enc2utf8(as.character(x))
  # Text read with the wrong encoding can contain bytes that are not valid
  # UTF-8, which would make every regular expression fail with an error.
  # Such bytes are shown as "<ff>" etc., so the value stays visible but can
  # no longer match anything and is reported as invalid.
  bad <- !is.na(x) & !validUTF8(x)
  if (any(bad)) {
    x[bad] <- iconv(x[bad], "UTF-8", "UTF-8", sub = "byte")
  }
  x
}

# Repair the most common non-canonical Bengali vowel-sign sequences so that
# pattern matching does not depend on how the text was typed.
# U+09C7 U+09BE -> U+09CB (o-kar), U+09C7 U+09D7 -> U+09CC (au-kar).
.bn_compose <- function(x) {
  x <- gsub("\u09c7\u09be", "\u09cb", x, fixed = TRUE)
  gsub("\u09c7\u09d7", "\u09cc", x, fixed = TRUE)
}

.squish <- function(x, strip_quotes = TRUE) {
  # Zero-width space (U+200B) and byte-order mark (U+FEFF, often at the start
  # of a CSV file) are invisible and never meaningful in these fields.
  x <- gsub("[\u200b\ufeff]", "", x, perl = TRUE)
  # Every kind of space (\p{Zs} covers the non-breaking, thin and en spaces
  # that word processors and web pages insert) becomes one ordinary space.
  x <- gsub("[\\s\\p{Zs}]+", " ", x, perl = TRUE)
  x <- gsub("^ | $", "", x, perl = TRUE)
  if (strip_quotes) {
    # Quotes wrapped around a whole value ("'0171..." is Excel's text marker).
    x <- gsub("^[\"'\u201c\u201d\u2018\u2019]+|[\"'\u201c\u201d\u2018\u2019]+$", "", x, perl = TRUE)
  }
  gsub("^ | $", "", x, perl = TRUE)
}

# Unicode signs that look like + and - become ASCII: the minus sign (U+2212)
# and the full-width plus and hyphen-minus (U+FF0B, U+FF0D).
.ascii_signs <- function(x) {
  chartr("\u2212\uff0b\uff0d", "-+-", x)
}

.warn_invalid <- function(n, what, warn) {
  if (isTRUE(warn) && n > 0L) {
    warning(sprintf("%d non-missing value%s could not be %s and %s set to NA.",
                    n, if (n == 1L) "" else "s", what,
                    if (n == 1L) "was" else "were"),
            call. = FALSE)
  }
  invisible(NULL)
}

.check_flag <- function(x, name) {
  if (!is.logical(x) || length(x) != 1L || is.na(x)) {
    stop(sprintf("`%s` must be TRUE or FALSE.", name), call. = FALSE)
  }
  invisible(x)
}

.nonblank <- function(x) {
  x <- .as_utf8_chr(x)
  !is.na(x) & .squish(x) != ""
}

# Normalise Bangla text for matching (not for display):
# - letters with nukta written as one code point (U+09DC rra, U+09DD rha,
#   U+09DF yya) are decomposed to letter + nukta (U+09BC), the canonical form;
# - zero-width joiner and non-joiner (U+200C, U+200D) are removed;
# - long vowel signs ii (U+09C0) and uu (U+09C2) become short i (U+09BF) and
#   u (U+09C1), a frequent spelling variation;
# - o-kar and au-kar typed as two code points are composed (.bn_compose()).
.bn_key <- function(x) {
  x <- gsub("\u09dc", "\u09a1\u09bc", x, fixed = TRUE)
  x <- gsub("\u09dd", "\u09a2\u09bc", x, fixed = TRUE)
  x <- gsub("\u09df", "\u09af\u09bc", x, fixed = TRUE)
  x <- gsub("[\u200c\u200d]", "", x, perl = TRUE)
  x <- chartr("\u09c0\u09c2", "\u09bf\u09c1", x)
  .bn_compose(x)
}

# Remove the commas from correctly grouped numbers and leave every other
# comma in place, so that badly grouped text (for example "1,2,3") later fails
# to parse instead of being silently read as 123. Two groupings are accepted:
# international  1,234,567  (groups of three)
# South Asian    12,34,567  (a group of three, then groups of two)
.ungroup_digits <- function(x) {
  # Only touch non-missing strings that contain a digit-comma-digit run;
  # `regmatches<-` would otherwise turn NA into the string "NA".
  has <- !is.na(x) & grepl("[0-9],[0-9]", x, perl = TRUE)
  if (!any(has)) {
    return(x)
  }
  run <- "[0-9]+(?:,[0-9]+)+"
  valid <- "^(?:[0-9]{1,3}(?:,[0-9]{3})+|[0-9]{1,2}(?:,[0-9]{2})+,[0-9]{3})$"
  fix <- function(v) {
    ok <- grepl(valid, v, perl = TRUE)
    v[ok] <- gsub(",", "", v[ok], fixed = TRUE)
    v
  }
  y <- x[has]
  n_runs <- lengths(gregexpr(run, y, perl = TRUE))
  # Common case, one grouped number per string: fully vectorised.
  one <- n_runs == 1L
  if (any(one)) {
    y1 <- y[one]
    m <- regexpr(run, y1, perl = TRUE)
    len <- attr(m, "match.length")
    y[one] <- paste0(substr(y1, 1L, m - 1L),
                     fix(substr(y1, m, m + len - 1L)),
                     substr(y1, m + len, nchar(y1)))
  }
  # Rare case, several grouped numbers in one string ("1,25,000 or 1,50,000").
  if (any(!one)) {
    y2 <- y[!one]
    g <- gregexpr(run, y2, perl = TRUE)
    regmatches(y2, g) <- lapply(regmatches(y2, g), fix)
    y[!one] <- y2
  }
  x[has] <- y
  x
}

# Bangla digits -> English digits (used by every parser).
.bn2en <- function(x) chartr(.bn_digits, .en_digits, .as_utf8_chr(x))

# Return a tibble when the tibble package is installed, else a data frame.
# bdscrub itself needs only base R; tibble is a suggested package.
.as_tbl <- function(df) {
  rownames(df) <- NULL
  if (requireNamespace("tibble", quietly = TRUE)) tibble::as_tibble(df) else df
}

# "Kaliganj (Gazipur); Kaliganj (Jhenaidah)": a short list of places, at most
# `max` shown.
.fmt_places <- function(name, district, max = 6L) {
  p <- unique(paste0(name, " (", district, ")"))
  if (length(p) > max) {
    paste0(paste(p[seq_len(max)], collapse = "; "), "; and ", length(p) - max, " more")
  } else {
    paste(p, collapse = "; ")
  }
}

.check_string <- function(x, name) {
  if (!is.character(x) || length(x) != 1L || is.na(x)) {
    stop(sprintf("`%s` must be a single string.", name), call. = FALSE)
  }
  invisible(x)
}

.check_distance <- function(x) {
  if (!is.numeric(x) || length(x) != 1L || is.na(x) || x < 0) {
    stop("`max_distance` must be a single non-negative number.", call. = FALSE)
  }
  invisible(x)
}

message("bdscrub 1.0.0 (one-file version) loaded.")
